// Plays Swedish speech generated by /api/speak. Only one thing plays at a
// time; starting a new one ends the old one. Long texts are split into
// sentence-sized chunks that play back to back, the next one fetched while
// the current one plays.
import { toaster } from "./toaster";
import { getStoredVoice } from "./voice";

export const WORD_RATE = 0.9;
export const TEXT_RATE = 1;

const MAX_CHUNK_CHARS = 450;
const SENTENCE_RE = /[^.!?…\n]+(?:[.!?…]+|\n+|$)\s*/g;
const HAS_LETTER_RE = /[A-Za-zÅÄÖåäö]/;

type Handlers = {
  rate?: number;
  // The [start, end) character range of `text` now being spoken.
  onRange?: (start: number, end: number) => void;
  onEnd?: () => void;
  onError?: (message: string) => void;
};

export type Chunk = { text: string; start: number; end: number };

function splitLong(start: number, raw: string): Chunk[] {
  const pieces: Chunk[] = [];
  let offset = 0;
  while (raw.length - offset > MAX_CHUNK_CHARS) {
    const window = raw.slice(offset, offset + MAX_CHUNK_CHARS);
    const cut = window.lastIndexOf(" ");
    const len = cut > 0 ? cut + 1 : MAX_CHUNK_CHARS;
    pieces.push({ text: raw.slice(offset, offset + len), start: start + offset, end: start + offset + len });
    offset += len;
  }
  pieces.push({ text: raw.slice(offset), start: start + offset, end: start + raw.length });
  return pieces;
}

// Groups whole sentences into chunks of at most MAX_CHUNK_CHARS, keeping
// each chunk's position in `content` so callers can highlight it.
export function chunkText(content: string): Chunk[] {
  const sentences: Chunk[] = [];
  for (const m of content.matchAll(SENTENCE_RE)) {
    const raw = m[0];
    const lead = raw.length - raw.trimStart().length;
    const trimmed = raw.trim();
    if (!HAS_LETTER_RE.test(trimmed)) continue;
    sentences.push(...splitLong(m.index! + lead, trimmed));
  }

  const chunks: Chunk[] = [];
  for (const s of sentences) {
    const last = chunks[chunks.length - 1];
    if (last && s.end - last.start <= MAX_CHUNK_CHARS) {
      last.end = s.end;
      last.text = content.slice(last.start, last.end);
    } else {
      chunks.push({ ...s });
    }
  }
  return chunks;
}

class QuotaError extends Error {}

// Every click would otherwise stack another identical toast.
const QUOTA_TOAST_COOLDOWN_MS = 15_000;
let lastQuotaToast = 0;

function notifyQuotaReached() {
  const now = Date.now();
  if (now - lastQuotaToast < QUOTA_TOAST_COOLDOWN_MS) return;
  lastQuotaToast = now;
  toaster.add({ title: "Voice unavailable", description: "Limit reached", type: "warning" });
}

let session = 0;
let currentAudio: HTMLAudioElement | null = null;
let abortPlay: (() => void) | null = null;
let endCurrent: (() => void) | null = null;

export function stopSpeaking(): void {
  session++;
  abortPlay?.();
  abortPlay = null;
  currentAudio?.pause();
  currentAudio = null;
  const end = endCurrent;
  endCurrent = null;
  end?.();
}

async function fetchAudio(text: string, voice: string): Promise<string> {
  const res = await fetch(`/api/speak?text=${encodeURIComponent(text)}&voice=${voice}`);
  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    if (body.code === "quota") throw new QuotaError();
    throw new Error(body.error ?? `Couldn't generate audio (${res.status})`);
  }
  return URL.createObjectURL(await res.blob());
}

function play(url: string, rate: number): Promise<void> {
  return new Promise((resolve, reject) => {
    const audio = new Audio(url);
    audio.playbackRate = rate;
    currentAudio = audio;
    abortPlay = resolve;
    audio.onended = () => resolve();
    audio.onerror = () => reject(new Error("Couldn't play the audio."));
    audio.play().catch(() => reject(new Error("Your browser blocked audio playback.")));
  });
}

export function speak(text: string, { rate = TEXT_RATE, onRange, onEnd, onError }: Handlers = {}): void {
  stopSpeaking();
  const chunks = chunkText(text);
  if (chunks.length === 0) return;

  const id = ++session;
  const voice = getStoredVoice();
  const urls: string[] = [];

  let finished = false;
  const finish = () => {
    if (finished) return;
    finished = true;
    if (endCurrent === finish) endCurrent = null;
    onEnd?.();
  };
  endCurrent = finish;

  const load = async (i: number) => {
    const url = await fetchAudio(chunks[i].text, voice);
    if (id !== session) {
      URL.revokeObjectURL(url);
      throw new Error("superseded");
    }
    urls.push(url);
    return url;
  };

  void (async () => {
    try {
      let next = load(0);
      for (let i = 0; i < chunks.length; i++) {
        const url = await next;
        if (i + 1 < chunks.length) {
          next = load(i + 1);
          next.catch(() => {}); // surfaced when awaited; don't flag it while prefetching
        }
        onRange?.(chunks[i].start, chunks[i].end);
        await play(url, rate);
        if (id !== session) return;
      }
    } catch (err) {
      if (id === session) {
        if (err instanceof QuotaError) notifyQuotaReached();
        else onError?.(err instanceof Error ? err.message : "Couldn't play audio.");
      }
    } finally {
      urls.forEach((u) => URL.revokeObjectURL(u));
      if (id === session) finish();
    }
  })();
}
